          <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
        </form>
      </li>`).join('')}</ul>`);
  }

  function projectPage(project, filter, priorityFilter = 'All', error = '', range = { from: '', through: '' }, search = '') {
